-- Generated by medallion from spec/tables/silver_payments.toml. Do not edit by hand.
-- Typed rows with expectations applied; the input to the change flow.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.payments_validated (
  payment_id STRING COMMENT 'Payment identifier',
  order_id STRING COMMENT 'Order the payment settles',
  amount DECIMAL(18,2) COMMENT 'Payment amount',
  currency STRING COMMENT 'ISO currency code, upper case',
  method STRING COMMENT 'Payment method, lower case',
  paid_at TIMESTAMP COMMENT 'When the payment settled (UTC)',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  op STRING COMMENT 'Change operation, used for deletes only',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row',
  CONSTRAINT payment_id_present EXPECT (payment_id IS NOT NULL AND length(payment_id) > 0) ON VIOLATION DROP ROW,
  CONSTRAINT order_id_present EXPECT (order_id IS NOT NULL AND length(order_id) > 0) ON VIOLATION DROP ROW,
  CONSTRAINT amount_positive EXPECT (amount IS NOT NULL AND amount > 0) ON VIOLATION DROP ROW,
  CONSTRAINT paid_at_valid EXPECT (paid_at IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT updated_at_valid EXPECT (updated_at IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT method_known EXPECT (method IN ('card', 'bank_transfer', 'wallet')),
  CONSTRAINT op_present EXPECT (op IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT op_known EXPECT (op IS NULL OR op IN ('I', 'U', 'D')) ON VIOLATION FAIL UPDATE
)
COMMENT 'Staging for silver.payments: typed rows that passed validation. Not for consumers.'
TBLPROPERTIES (
  'governance.owner' = 'finance-data',
  'governance.domain' = 'finance',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/silver_payments.toml',
  'governance.role' = 'staging'
)
AS SELECT
  try_cast(trim(payment_id) AS STRING) AS payment_id,
  try_cast(trim(order_id) AS STRING) AS order_id,
  try_cast(trim(amount) AS DECIMAL(18,2)) AS amount,
  try_cast(upper(trim(currency)) AS STRING) AS currency,
  try_cast(lower(trim(method)) AS STRING) AS method,
  try_cast(trim(paid_at) AS TIMESTAMP) AS paid_at,
  try_cast(trim(updated_at) AS TIMESTAMP) AS updated_at,
  try_cast(upper(trim(op)) AS STRING) AS op,
  _source_file,
  _ingested_at
FROM STREAM(${catalog}.bronze.payments);

-- The consumer-facing table. SCD type 1: one row per key.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.payments (
  payment_id STRING COMMENT 'Payment identifier',
  order_id STRING COMMENT 'Order the payment settles',
  amount DECIMAL(18,2) COMMENT 'Payment amount',
  currency STRING COMMENT 'ISO currency code, upper case',
  method STRING COMMENT 'Payment method, lower case',
  paid_at TIMESTAMP COMMENT 'When the payment settled (UTC)',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row'
)
COMMENT 'Current state of each payment: typed, validated and deduplicated by key. Bad rows go to the quarantine table.'
TBLPROPERTIES (
  'governance.owner' = 'finance-data',
  'governance.domain' = 'finance',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/silver_payments.toml',
  'governance.role' = 'serving'
);

CREATE FLOW silver_payments_apply_changes AS AUTO CDC INTO ${catalog}.silver.payments
FROM STREAM(${catalog}.silver.payments_validated)
KEYS (payment_id)
APPLY AS DELETE WHEN op = 'D'
SEQUENCE BY updated_at
COLUMNS * EXCEPT (op)
STORED AS SCD TYPE 1;

-- Rows that failed a drop expectation, kept for investigation and replay.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.payments_quarantine (
  payment_id STRING COMMENT 'Payment identifier',
  order_id STRING COMMENT 'Order the payment settles',
  amount DECIMAL(18,2) COMMENT 'Payment amount',
  currency STRING COMMENT 'ISO currency code, upper case',
  method STRING COMMENT 'Payment method, lower case',
  paid_at TIMESTAMP COMMENT 'When the payment settled (UTC)',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  op STRING COMMENT 'Change operation, used for deletes only',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row',
  failed_rules ARRAY<STRING> COMMENT 'Names of the drop expectations this row failed'
)
COMMENT 'Rows from bronze.payments that failed a drop expectation for silver.payments, with the rules they failed.'
TBLPROPERTIES (
  'governance.owner' = 'finance-data',
  'governance.domain' = 'finance',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/silver_payments.toml',
  'governance.role' = 'quarantine'
)
AS SELECT
  *,
  filter(array(
    CASE WHEN coalesce(payment_id IS NOT NULL AND length(payment_id) > 0, false) THEN NULL ELSE 'payment_id_present' END,
    CASE WHEN coalesce(order_id IS NOT NULL AND length(order_id) > 0, false) THEN NULL ELSE 'order_id_present' END,
    CASE WHEN coalesce(amount IS NOT NULL AND amount > 0, false) THEN NULL ELSE 'amount_positive' END,
    CASE WHEN coalesce(paid_at IS NOT NULL, false) THEN NULL ELSE 'paid_at_valid' END,
    CASE WHEN coalesce(updated_at IS NOT NULL, false) THEN NULL ELSE 'updated_at_valid' END,
    CASE WHEN coalesce(op IS NOT NULL, false) THEN NULL ELSE 'op_present' END
  ), x -> x IS NOT NULL) AS failed_rules
FROM (
  SELECT
    try_cast(trim(payment_id) AS STRING) AS payment_id,
    try_cast(trim(order_id) AS STRING) AS order_id,
    try_cast(trim(amount) AS DECIMAL(18,2)) AS amount,
    try_cast(upper(trim(currency)) AS STRING) AS currency,
    try_cast(lower(trim(method)) AS STRING) AS method,
    try_cast(trim(paid_at) AS TIMESTAMP) AS paid_at,
    try_cast(trim(updated_at) AS TIMESTAMP) AS updated_at,
    try_cast(upper(trim(op)) AS STRING) AS op,
    _source_file,
    _ingested_at
  FROM STREAM(${catalog}.bronze.payments)
)
WHERE NOT coalesce((payment_id IS NOT NULL AND length(payment_id) > 0) AND (order_id IS NOT NULL AND length(order_id) > 0) AND (amount IS NOT NULL AND amount > 0) AND (paid_at IS NOT NULL) AND (updated_at IS NOT NULL) AND (op IS NOT NULL), false);
